def respond(browser, status, message):
    body = message.encode()
    browser.sendall(
        f"HTTP/1.1 {status}\r\n"
        "Content-Type: text/plain; charset=utf-8\r\n"
        f"Content-Length: {len(body)}\r\n"
        "Connection: close\r\n"
        "\r\n".encode() + body
    )
    browser.shutdown(socket.SHUT_WR)


def read_request(browser, limit=16384):
    buf = b""
    while b"\r\n\r\n" not in buf and len(buf) < limit:
        try:
            chunk = browser.recv(4096)
        except OSError:
            break
        if not chunk:
            break
        buf += chunk
    return buf


def request_target(browser, expected, state):
    browser.settimeout(30)
    raw = read_request(browser)
    if b"\r\n\r\n" not in raw:
        log(f"callback port got no request: {raw[:60]!r}")
        return None
    request = raw.split(b"\r\n", 1)[0].decode("latin-1")
    method, _, rest = request.partition(" ")
    target = rest.rpartition(" ")[0]
