def read_line(sock, limit=8192):
    buf = b""
    while not buf.endswith(b"\n") and len(buf) < limit:
        chunk = sock.recv(1)
        if not chunk:
            break
        buf += chunk
    return buf.decode("utf-8", "replace").strip()


# A relay socket means this machine is not the browser host
def dial_relay():
    try:
        if not stat.S_ISSOCK(os.stat(RELAY).st_mode):
            return None
    except OSError:
        return None
    upstream = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
