                chunk = key.fileobj.recv(65536)
                if not chunk:
                    selector.unregister(key.fileobj)
                    try:
                        onward[key.fileobj].shutdown(socket.SHUT_WR)
                    except OSError:
                        pass
                    continue
                onward[key.fileobj].sendall(chunk)


